q, safety = build_query("SELECT * FROM users WHERE name = ?", ["O'Brien"])
assert safety == 'parameterized'
assert "O'Brien" in q  # the apostrophe survives, structure unchanged
try:
    build_query("SELECT ?", [1, 2])
except UnsafeQuery:
    pass
else:
    raise AssertionError('count mismatch must raise')
print('ok')

try:
    vulnerable_query("SELECT * FROM t WHERE a = '{}'", ["x'; DROP TABLE t; --"])
except UnsafeQuery:
    pass
else:
    raise AssertionError('must flag the payload')
assert vulnerable_query("SELECT * FROM t WHERE a = '{}'", ['bob']) == "SELECT * FROM t WHERE a = 'bob'"
print('ok')
